# Fabricated endpoint reuse fixture only: a fit function is replaced locally by
# a fail-closed sentinel. No real count inputs, model fits, or package overrides.
args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 1L) stop("Provide source directory")
source(file.path(args[1L], "deseq2_core.R")); source(file.path(args[1L], "revision_io.R")); source(file.path(args[1L], "revision_models.R"))
core <- normalizePath(file.path(args[1L], "deseq2_core.R"), mustWork = TRUE)
options(satb2.revision.statistical_core_sha256 = sha_file(core))
satb2_pb_fit_deseq2 <- function(...) stop("FIT_SENTINEL: fitting is forbidden in this fabricated cache fixture")
fixture <- tempfile("satb2_revision_SYNTHETIC_CACHE_"); dir.create(fixture)
samples <- names(satb2_pb_roster()); y <- matrix(10L, 3L, 12L, dimnames = list(paste0("FAKE", 1:3), samples))
genes <- data.frame(gene_id = rownames(y), gene_symbol = c("FakeA", "FakeA", NA_character_), display_symbol = c("FakeA", "FakeA", NA_character_), symbol_missing = c(FALSE,FALSE,TRUE))
md <- data.frame(sample = samples, condition = unname(satb2_pb_roster()), sequencing_partition = unname(satb2_pb_expected_partitions()), n_nuclei = 1L, total_UMIs = colSums(y)); rownames(md) <- samples
selection <- satb2_pb_select(md, "PRIMARY", min_nuclei = 1L); pf <- satb2_pb_prefilter(y, selection, TRUE)
universe <- pf$gene_id[pf$passes_primary_prefilter]; prepared <- satb2_pb_prepare_endpoint(y, selection, universe)
old <- new_dir(file.path(fixture, "old_endpoint")); audit <- new_dir(file.path(old, "AUDIT")); stage <- new_dir(file.path(fixture, "prior_stage"))
needed <- c("Matrix", "DESeq2", "S4Vectors", "SummarizedExperiment")
write_tsv(data.frame(package = c("R", needed), version = c(as.character(getRversion()), vapply(needed, function(p) as.character(utils::packageVersion(p)), character(1)))), file.path(stage, "PACKAGE_VERSIONS.tsv"))
satb2_pb_write_text("Synthetic fixture; no scientific fit", file.path(stage, "SESSION_INFO.txt"))
write_tsv(data.frame(gene_id=rownames(y),y,check.names=FALSE),file.path(fixture,"counts.tsv"));write_tsv(pf,file.path(fixture,"FROZEN_PRIMARY_GENE_PREFILTER_AUDIT.tsv"))
write_tsv(selection$audit,file.path(audit,"MICE_ALL12_AUDIT.tsv"));write_tsv(prepared$audit,file.path(audit,"GENE_UNIVERSE_AUDIT.tsv"))
settings<-c(method="DESeq2",design=selection$design,numerator="cKO",denominator="WT",biological_unit="independent_mouse",independentFiltering="TRUE",cooksCutoff="DESeq2_default; NA_retained",automatic_count_replacement="disabled",normalization="poscounts",statistic="signed_Wald",alpha="0.05")
write_tsv(data.frame(setting=names(settings),value=unname(settings)),file.path(audit,"MODEL_SETTINGS.tsv"))
z<-data.frame(gene_id=rownames(y),baseMean=10,log2FoldChange=c(0,1,-1),lfcSE=1,stat=c(0,1,-1),pvalue=c(1,.1,NA),padj=c(1,.2,NA))
satb2_pb_export_results(z,genes,old,audit)
write_tsv(data.frame(status="TESTED_REVIEW_REQUIRED",warning_count=0L,n_WT=6L,n_cKO=6L,residual_df=10L,design=selection$design,n_pvalue=2L,n_padj=2L,DEG_FDR05=0L),file.path(audit,"EXECUTION_AUDIT.tsv"))
write_tsv(data.frame(sample=samples,fitted_size_factor=1),file.path(audit,"FITTED_SIZE_FACTORS.tsv"));satb2_pb_write_text("parametric",file.path(audit,"DISPERSION_FIT_TYPE.txt"));satb2_pb_write_text("No captured fitting warnings.",file.path(audit,"MODEL_WARNINGS.txt"))
write_tsv(data.frame(population_key="FAKE",nucleus_id=paste0(samples,"_FAKEBAR")),file.path(fixture,"members.tsv"));write_tsv(data.frame(population_key="FAKE",membership_sha256=member_sha(paste0(samples,"_FAKEBAR"))),file.path(fixture,"index.tsv"))
hash<-member_sha(paste0(samples,"_FAKEBAR"))
candidate<-revision_candidate(file.path(fixture,"counts.tsv"),fixture,old,stage,core,file.path(fixture,"members.tsv"),file.path(fixture,"index.tsv"),hash)
check<-satb2_pb_cache(candidate,y,selection,prepared,universe,TRUE,hash);stopifnot(isTRUE(check$accepted))
ans<-satb2_pb_run_endpoint(y,md,genes,universe,file.path(fixture,"new_endpoint"),min_nuclei=1L,gene_count_cutoff=5L,gene_required_mice=3L,count_kind="SYNTHETIC_NOT_STUDY",cache=candidate,membership_sha256=hash)
stopifnot(ans$audit$status=="TESTED_REVIEW_REQUIRED",ans$audit$execution_origin=="REUSED_EXACT_UNCHANGED_DESEQ2_ENDPOINT",ans$audit$coverage_flag=="LOW_NUCLEUS_COVERAGE_EXPLORATORY")
stopifnot(identical(names(read_tsv(file.path(fixture,"new_endpoint","ALL_RESULTS.txt"))),satb2_pb_result_columns()))
bad<-y;bad[1,1]<-11L;stopifnot(!isTRUE(satb2_pb_cache(candidate,bad,selection,prepared,universe,TRUE,hash)$accepted))
stopifnot(!isTRUE(satb2_pb_cache(candidate,y,selection,prepared,universe,TRUE,member_sha('DIFFERENT'))$accepted))
stopifnot(!isTRUE(satb2_pb_cache(candidate,y,selection,prepared,universe,FALSE,hash)$accepted))
finalized<-new_dir(file.path(fixture,'accepted_definitions'));write_tsv(data.frame(population_key='FAKE'),file.path(finalized,'POPULATION_INDEX.tsv'));write_tsv(data.frame(population_key='FAKE',atomic_population_key='ATOM'),file.path(finalized,'POPULATION_ATOMS.tsv'))
master<-file.path(fixture,'MASTER.json');writeLines('{}',master);options(satb2.revision.master_config_sha256=sha_file(master))
paths<-normalizePath(file.path(finalized,c('POPULATION_INDEX.tsv','POPULATION_ATOMS.tsv')),mustWork=TRUE)
receipt<-list(exact_integer_counts_PASS=TRUE,config_sha256=sha_file(master),validated_sources=setNames(as.list(vapply(paths,sha_file,character(1))),paths))
receipt_path<-file.path(fixture,'COUNT_ACCEPTANCE.json');jsonlite::write_json(receipt,receipt_path,auto_unbox=TRUE)
sc<-list(count_acceptance_json_by_branch=list(original_full=receipt_path));stopifnot(isTRUE(verify_count_acceptance(sc,'original_full',finalized)))
receipt$config_sha256<-sha_file(core);jsonlite::write_json(receipt,receipt_path,auto_unbox=TRUE)
reject<-tryCatch({verify_count_acceptance(sc,'original_full',finalized);FALSE},error=function(e)grepl('current immutable master',conditionMessage(e)));stopifnot(reject)
receipt$config_sha256<-sha_file(master);receipt$validated_sources[[paths[1]]]<-sha_file(core);jsonlite::write_json(receipt,receipt_path,auto_unbox=TRUE)
reject<-tryCatch({verify_count_acceptance(sc,'original_full',finalized);FALSE},error=function(e)grepl('SHA256/input guard failed',conditionMessage(e)));stopifnot(reject)
cat("SYNTHETIC endpoint reuse exact counts/membership/runtime/policy, changed count/membership/policy rejection, IN low-coverage flag and seven-symbol-field export PASS; fitting sentinel was not called.\n")
cat("SYNTHETIC independent count acceptance current-master/consumed-final-definition binding PASS; stale master/changed definition rejected before fitting.\n")
